private Transaction parseLine(
        String line,
        Function<UUID, Account> accountResolver,
        TransactionCreationService creationService) {
    String[] cols = line.split(",", -1);
    UUID accountId = UUID.fromString(cols[0]);
    Account account = accountResolver.apply(accountId);
    if (account == null) {
        throw new IllegalStateException("unknown accountId in CSV row: " + accountId);
