                                  Repository<Account, UUID> accounts) {
        this.transactionCreationService = transactionCreationService;
        this.accounts = accounts;
    }

    @PostMapping("/transactions")
    public ResponseEntity<TransactionResponse> create(@Valid @RequestBody CreateTransactionRequest request) {
        UUID accountId = UUID.fromString(request.accountId());
        Account account = accounts.find(accountId)
                .orElseThrow(() -> new AccountNotFoundException(accountId));
        String sourceRef = "MANUAL:" + UUID.randomUUID();
